1, 2, 1 ); dummy.updateMatrix(); color.setHSL( 1, 0.5 + ( Math.random() \* 0.5 ), 0.5 + ( Math.random() \* 0.5 ) ); baseColors.push( color.getHex() ); mesh.setMatrixAt( i, dummy.matrix ); mesh.setColorAt( i, color.multiply( colors\[ 0 \] ) ); i ++; seeds.push( Math.random() ); } } // window.addEventListener( 'resize', onWindowResize ); setInterval( startTween, 3000 ); } function startTween() { // tween for animating color transition new TWEEN.Tween( animation ) .to( { t: 1 }, 2000 ) .easing( TWEEN.Easing.Sinusoidal.In ) .onComplete( () => { animation.t = 0; currentColorIndex = nextColorIndex; nextColorIndex ++; if ( nextColorIndex >= colors.length ) nextColorIndex = 0; } ) .start(); } function onWindowResize() { camera.aspect = window.innerWidth / window.innerHeight; camera.updateProjectionMatrix(); renderer.setSize( window.innerWidth, window.innerHeight ); } // function animate() { timer.update(); const time = timer.getElapsed(); TWEEN.update(); // animate camera camera.position.x = Math.sin( time / 4 ) \* 10; camera.position.z = Math.cos( time / 4 ) \* 10; camera.position.y = 8 + Math.cos( time / 2 ) \* 2; cameraTarget.x = Math.sin( time / 4 ) \* - 8; cameraTarget.z = Math.cos( time / 2 ) \* - 8; camera.lookAt( cameraTarget ); camera.up.x = Math.sin( time / 400 ); // animate instance positions and colors for ( let i = 0; i < mesh.count; i ++ ) { mesh.getMatrixAt( i, dummy.matrix ); dummy.matrix.decompose( dummy.position, dummy.quaternion, dummy.scale ); dummy.position.y = Math.abs( Math.sin( ( time + seeds\[ i \] ) \* 2 + seeds\[ i \] ) ); dummy.updateMatrix(); mesh.setMatrixAt( i, dummy.matrix ); // colors if ( animation.t > 0 ) { const currentColor = colors\[ currentColorIndex \]; const nextColor = colors\[ nextColorIndex \]; const f = dummy.position.length() / maxDistance; if ( f <= animation.t ) { color.set( baseColors\[ i \] ).multiply( nextColor ); } else { color.set( baseColors\[ i \] ).multiply( currentColor ); } mesh.setColorAt( i, color ); } } mesh.instanceMatrix.needsUpdate = true; if ( animation.t > 0 ) mesh.instanceColor.needsUpdate = true; mesh.computeBoundingSphere(); renderer.render( scene, camera ); }
