export const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
export const lerp = (a, b, t) => a + (b - a) * t;
export const inverseLerp = (a, b, value) => (a === b ? 0 : (value - a) / (b - a));

export function smoothstep(min, max, value) {
  const t = clamp(inverseLerp(min, max, value), 0, 1);
  return t * t * (3 - 2 * t);
}

export const easeOutCubic = (t) => 1 - (1 - clamp(t, 0, 1)) ** 3;

export function approach(value, target, maxDelta) {
  if (value < target) return Math.min(value + maxDelta, target);
  if (value > target) return Math.max(value - maxDelta, target);
  return target;
}

export function mulberry32(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let value = state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
}

export function weightedIndex(weights, count, randomValue) {
  let total = 0;
  for (let i = 0; i < count; i += 1) total += Math.max(0, weights[i]);
  if (total <= 0) return -1;
  let cursor = clamp(randomValue, 0, 0.999999999) * total;
  for (let i = 0; i < count; i += 1) {
    cursor -= Math.max(0, weights[i]);
    if (cursor < 0) return i;
  }
  return count - 1;
}

import { clamp } from './MathUtils.js';

export function setAabb(target, centerX, centerY, halfWidth, halfHeight) {
  target.minX = centerX - halfWidth;
  target.maxX = centerX + halfWidth;
  target.minY = centerY - halfHeight;
  target.maxY = centerY + halfHeight;
  return target;
}

export function aabbOverlaps(a, b) {
  return a.minX <= b.maxX && a.maxX >= b.minX && a.minY <= b.maxY && a.maxY >= b.minY;
}

export function pointInAabb(x, y, box) {
  return x >= box.minX && x <= box.maxX && y >= box.minY && y <= box.maxY;
}

export function sweptAabb(x0, y0, x1, y1, halfWidth, halfHeight, target, result) {
  const minX = target.minX - halfWidth;
  const maxX = target.maxX + halfWidth;
  const minY = target.minY - halfHeight;
  const maxY = target.maxY + halfHeight;
  const dx = x1 - x0;
  const dy = y1 - y0;

  let enterX = -Infinity;
  let exitX = Infinity;
  if (Math.abs(dx) < 1e-10) {
    if (x0 < minX || x0 > maxX) return false;
  } else {
    const tx1 = (minX - x0) / dx;
    const tx2 = (maxX - x0) / dx;
    enterX = Math.min(tx1, tx2);
    exitX = Math.max(tx1, tx2);
  }

  let enterY = -Infinity;
  let exitY = Infinity;
  if (Math.abs(dy) < 1e-10) {
    if (y0 < minY || y0 > maxY) return false;
  } else {
    const ty1 = (minY - y0) / dy;
    const ty2 = (maxY - y0) / dy;
    enterY = Math.min(ty1, ty2);
    exitY = Math.max(ty1, ty2);
  }

  const enter = Math.max(enterX, enterY, 0);
  const exit = Math.min(exitX, exitY, 1);
  if (enter > exit || exit < 0 || enter > 1) return false;

  result.time = clamp(enter, 0, 1);
  result.x = x0 + dx * result.time;
  result.y = y0 + dy * result.time;
  if (enterX > enterY) {
    result.nx = dx > 0 ? -1 : 1;
    result.ny = 0;
  } else {
    result.nx = 0;
    result.ny = dy > 0 ? -1 : 1;
  }
  return true;
}

const createRecord = () => ({
  type: '',
  x: 0,
  y: 0,
  z: 0,
  nx: 0,
  ny: 1,
  speed: 0,
  value: 0,
  priority: 0,
  source: -1,
  target: -1,
  variant: 0,
  text: '',
  cause: '',
});

export class EventQueue {
  constructor(capacity = 256) {
    this.capacity = capacity;
    this.records = Array.from({ length: capacity }, createRecord);
    this.readIndex = 0;
    this.writeIndex = 0;
    this.count = 0;
    this.dropped = 0;
  }

  push(type) {
    if (this.count >= this.capacity) {
      this.dropped += 1;
      return null;
    }

    const record = this.records[this.writeIndex];
    record.type = type;
    record.x = 0;
    record.y = 0;
    record.z = 0;
    record.nx = 0;
    record.ny = 1;
    record.speed = 0;
    record.value = 0;
    record.priority = 0;
    record.source = -1;
    record.target = -1;
    record.variant = 0;
    record.text = '';
    record.cause = '';

    this.writeIndex = (this.writeIndex + 1) % this.capacity;
    this.count += 1;
    return record;
  }

  drain(handler) {
    while (this.count > 0) {
      const record = this.records[this.readIndex];
      handler(record);
      this.readIndex = (this.readIndex + 1) % this.capacity;
      this.count -= 1;
    }
    this.writeIndex = this.readIndex;
  }

  clear() {
    this.readIndex = 0;
    this.writeIndex = 0;
    this.count = 0;
    this.dropped = 0;
  }
}

const ACTION_NAMES = ['fire', 'confirm', 'pause', 'restart', 'mute'];

export const DEFAULT_BINDINGS = Object.freeze({
  left: ['KeyA', 'ArrowLeft'],
  right: ['KeyD', 'ArrowRight'],
  fire: ['Space'],
  confirm: ['Enter', 'Space'],
  pause: ['Escape', 'KeyP'],
  restart: ['KeyR'],
  mute: ['KeyM'],
});

const isAnyDown = (keys, codes) => codes.some((code) => keys.has(code));

export class InputController {
  constructor({ bindings = DEFAULT_BINDINGS, deadZone = 0.2, onGamepadChange = () => {} } = {}) {
    this.bindings = bindings;
    this.deadZone = deadZone;
    this.onGamepadChange = onGamepadChange;
    this.keys = new Set();
    this.abortController = new AbortController();
    this.previous = Object.fromEntries(ACTION_NAMES.map((name) => [name, false]));
    this.current = Object.fromEntries(ACTION_NAMES.map((name) => [name, false]));
    this.snapshot = {
      axisX: 0,
      fire: false,
      confirm: false,
      pause: false,
      restart: false,
      mute: false,
      firePressed: false,
      confirmPressed: false,
      pausePressed: false,
      restartPressed: false,
      mutePressed: false,
      usingGamepad: false,
    };
    this.activeGamepadIndex = -1;
    this._installListeners();
  }

  _installListeners() {
    const options = { signal: this.abortController.signal };
    window.addEventListener('keydown', (event) => {
      if (this._isBoundCode(event.code)) event.preventDefault();
      this.keys.add(event.code);
    }, options);
    window.addEventListener('keyup', (event) => {
      if (this._isBoundCode(event.code)) event.preventDefault();
      this.keys.delete(event.code);
    }, options);
    window.addEventListener('blur', () => this.clear(), options);
    window.addEventListener('gamepadconnected', (event) => {
      this.activeGamepadIndex = event.gamepad.index;
      this.onGamepadChange(true, event.gamepad.id);
    }, options);
    window.addEventListener('gamepaddisconnected', (event) => {
      if (event.gamepad.index === this.activeGamepadIndex) this.activeGamepadIndex = -1;
      this.onGamepadChange(false, event.gamepad.id);
    }, options);
  }

  _isBoundCode(code) {
    return Object.values(this.bindings).some((codes) => codes.includes(code));
  }

  _applyDeadZone(value) {
    const magnitude = Math.abs(value);
    if (magnitude <= this.deadZone) return 0;
    return Math.sign(value) * ((magnitude - this.deadZone) / (1 - this.deadZone));
  }

  _getGamepad() {
    if (typeof navigator === 'undefined' || typeof navigator.getGamepads !== 'function') return null;
    const pads = navigator.getGamepads();
    if (this.activeGamepadIndex >= 0 && pads[this.activeGamepadIndex]) return pads[this.activeGamepadIndex];
    for (const pad of pads) {
      if (pad?.connected) {
        this.activeGamepadIndex = pad.index;
        return pad;
      }
    }
    return null;
  }

  update() {
    const keyboardAxis = (isAnyDown(this.keys, this.bindings.right) ? 1 : 0)
      - (isAnyDown(this.keys, this.bindings.left) ? 1 : 0);
    const pad = this._getGamepad();
    let gamepadAxis = 0;
    let padFire = false;
    let padPause = false;
