    const t = smoothstep(0, this.interval * 0.72, this.beatTimer);
    return this.previousX + (this.originX - this.previousX) * t;
  }

  renderY() {
    const t = smoothstep(0, this.interval * 0.72, this.beatTimer);
    return this.previousY + (this.originY - this.previousY) * t;
  }
