import { setAabb, sweptAabb } from '../../shared/math/Collision.js';
import { lerp } from '../../shared/math/MathUtils.js';
import { CONFIG, EVENT_TYPES, VFX_PRIORITY } from '../config.js';

export class CombatSystem {
  constructor() {
    this.targetBox = { minX: 0, maxX: 0, minY: 0, maxY: 0 };
    this.hit = { time: 0, x: 0, y: 0, nx: 0, ny: 0 };
    this.best = { time: Infinity, x: 0, y: 0, nx: 0, ny: 0, target: -1 };
  }

  update(dt, simulation) {
    this._integrateProjectiles(dt, simulation);
    this._resolvePlayerProjectiles(simulation);
    this._resolveEnemyProjectiles(simulation);
    this._erodeBunkersByFormation(simulation);
  }

  _integrateProjectiles(dt, simulation) {
    const player = simulation.playerProjectiles;
    for (let id = 0; id < player.capacity; id += 1) {
      if (!player.pool.isActive(id)) continue;
      player.previousX[id] = player.x[id];
      player.previousY[id] = player.y[id];
      player.x[id] += player.vx[id] * dt;
      player.y[id] += player.vy[id] * dt;
      player.age[id] += dt;
      if (player.y[id] > CONFIG.world.projectileTop) player.release(id);
    }

    const enemy = simulation.enemyProjectiles;
    for (let id = 0; id < enemy.capacity; id += 1) {
      if (!enemy.pool.isActive(id)) continue;
      enemy.previousX[id] = enemy.x[id];
      enemy.previousY[id] = enemy.y[id];
      enemy.age[id] += dt;
      if (enemy.kind[id] === 1) {
        enemy.y[id] += enemy.vy[id] * dt;
        enemy.x[id] = enemy.originX[id] + 0.34 * Math.sin(enemy.phase[id] + enemy.age[id] * 8.5);
      } else {
        enemy.x[id] += enemy.vx[id] * dt;
        enemy.y[id] += enemy.vy[id] * dt;
      }
      if (
        enemy.y[id] < CONFIG.world.projectileBottom
        || enemy.x[id] < CONFIG.world.left - 2
        || enemy.x[id] > CONFIG.world.right + 2
      ) enemy.release(id);
    }
  }

  _resolvePlayerProjectiles(simulation) {
    const pool = simulation.playerProjectiles;
    for (let id = 0; id < pool.capacity; id += 1) {
      if (!pool.pool.isActive(id)) continue;
      this.best.time = Infinity;
      this.best.target = -1;
      let hitKind = 0;

      if (simulation.ufo.active) {
        setAabb(
          this.targetBox,
          simulation.ufo.x,
          simulation.ufo.y,
          CONFIG.ufo.halfWidth,
          CONFIG.ufo.halfHeight,
        );
        if (this._sweepProjectile(pool, id, this.targetBox) && this.hit.time < this.best.time) {
          this._copyBest(-2);
          hitKind = 1;
        }
      }

      for (let invader = 0; invader < simulation.invaders.capacity; invader += 1) {
        if (simulation.invaders.alive[invader] === 0) continue;
        const x = simulation.formation.originX + simulation.invaders.localX[invader];
        const y = simulation.formation.originY + simulation.invaders.localY[invader];
        setAabb(this.targetBox, x, y, CONFIG.formation.halfWidth, CONFIG.formation.halfHeight);
        if (this._sweepProjectile(pool, id, this.targetBox) && this.hit.time < this.best.time) {
          this._copyBest(invader);
          hitKind = 2;
        }
      }

      if (hitKind === 1) {
        simulation.killUfo(this.best.x, this.best.y, Math.abs(pool.vy[id]));
        pool.release(id);
        continue;
      }
      if (hitKind === 2) {
        simulation.killInvader(this.best.target, this.best.x, this.best.y, Math.abs(pool.vy[id]));
        pool.release(id);
        continue;
      }

      if (this._interceptEnemyProjectile(id, simulation)) {
        pool.release(id);
        continue;
      }

      const bunker = this._findBunkerHit(pool, id, simulation);
      if (bunker >= 0) {
        const x = this.hit.x;
        const y = this.hit.y;
        const removed = simulation.bunkers.erodeAt(x, y, 1, 1);
        if (removed > 0) this._emitBunkerHit(simulation, x, y, removed, 1);
        pool.release(id);
      }
    }
  }

  _resolveEnemyProjectiles(simulation) {
    const pool = simulation.enemyProjectiles;
    for (let id = 0; id < pool.capacity; id += 1) {
      if (!pool.pool.isActive(id)) continue;

      const bunker = this._findBunkerHit(pool, id, simulation);
      if (bunker >= 0) {
        const x = this.hit.x;
        const y = this.hit.y;
        const damageScale = 1 + simulation.wave * 0.025 + (pool.kind[id] === 2 ? 0.12 : 0);
        const removed = simulation.bunkers.erodeAt(x, y, -1, Math.min(1.35, damageScale));
        if (removed > 0) this._emitBunkerHit(simulation, x, y, removed, -1);
        pool.release(id);
        continue;
      }

      if (!simulation.player.active || simulation.player.invulnerabilityTimer > 0) continue;
      setAabb(
        this.targetBox,
        simulation.player.x,
        simulation.player.y,
        CONFIG.player.halfWidth,
        CONFIG.player.halfHeight,
      );
      if (this._sweepProjectile(pool, id, this.targetBox)) {
        simulation.hitPlayer(this.hit.x, this.hit.y, Math.hypot(pool.vx[id], pool.vy[id]));
        pool.release(id);
      }
    }
  }

  _interceptEnemyProjectile(playerId, simulation) {
    const player = simulation.playerProjectiles;
    const enemy = simulation.enemyProjectiles;
    let bestEnemy = -1;
    let bestTime = Infinity;
    for (let id = 0; id < enemy.capacity; id += 1) {
      if (!enemy.pool.isActive(id)) continue;
      setAabb(this.targetBox, enemy.x[id], enemy.y[id], enemy.halfWidth[id], enemy.halfHeight[id]);
      if (this._sweepProjectile(player, playerId, this.targetBox) && this.hit.time < bestTime) {
        bestTime = this.hit.time;
        bestEnemy = id;
        this._copyBest(id);
      }
    }
    if (bestEnemy < 0) return false;
    enemy.release(bestEnemy);
    simulation.addScore(5);
    const event = simulation.events.push(EVENT_TYPES.PROJECTILE_CLASH);
    if (event) {
      event.x = this.best.x;
      event.y = this.best.y;
      event.speed = CONFIG.player.projectileSpeed;
      event.priority = VFX_PRIORITY.MINOR;
    }
    return true;
  }

  _findBunkerHit(pool, projectileId, simulation) {
    const minPathY = Math.min(pool.previousY[projectileId], pool.y[projectileId]);
    const maxPathY = Math.max(pool.previousY[projectileId], pool.y[projectileId]);
    if (maxPathY < CONFIG.bunker.y - 1.2 || minPathY > CONFIG.bunker.y + 1.2) return -1;

    let bestId = -1;
    let bestTime = Infinity;
    for (let id = 0; id < simulation.bunkers.capacity; id += 1) {
      if (simulation.bunkers.alive[id] === 0) continue;
      const half = CONFIG.bunker.cellSize * 0.5;
      setAabb(this.targetBox, simulation.bunkers.x[id], simulation.bunkers.y[id], half, half);
      if (this._sweepProjectile(pool, projectileId, this.targetBox) && this.hit.time < bestTime) {
        bestTime = this.hit.time;
        bestId = id;
        this._copyBest(id);
      }
    }
    if (bestId >= 0) {
      this.hit.time = this.best.time;
      this.hit.x = this.best.x;
      this.hit.y = this.best.y;
      this.hit.nx = this.best.nx;
      this.hit.ny = this.best.ny;
    }
    return bestId;
  }

  _sweepProjectile(pool, id, target) {
    return sweptAabb(
      pool.previousX[id],
      pool.previousY[id],
      pool.x[id],
      pool.y[id],
      pool.halfWidth[id],
      pool.halfHeight[id],
      target,
      this.hit,
    );
  }

  _copyBest(target) {
    this.best.time = this.hit.time;
    this.best.x = this.hit.x;
    this.best.y = this.hit.y;
    this.best.nx = this.hit.nx;
    this.best.ny = this.hit.ny;
    this.best.target = target;
  }

  _emitBunkerHit(simulation, x, y, removed, direction) {
    const event = simulation.events.push(EVENT_TYPES.BUNKER_HIT);
    if (event) {
      event.x = x;
      event.y = y;
      event.value = removed;
      event.ny = direction;
      event.priority = VFX_PRIORITY.MINOR;
    }
  }

  _erodeBunkersByFormation(simulation) {
    if (simulation.formation.originY > -2.5) return;
    const halfCell = CONFIG.bunker.cellSize * 0.5;
    let removed = 0;
    let eventX = 0;
    let eventY = 0;
    for (let invader = 0; invader < simulation.invaders.capacity; invader += 1) {
      if (simulation.invaders.alive[invader] === 0) continue;
      const x = simulation.formation.originX + simulation.invaders.localX[invader];
      const y = simulation.formation.originY + simulation.invaders.localY[invader];
      for (let cell = 0; cell < simulation.bunkers.capacity; cell += 1) {
        if (simulation.bunkers.alive[cell] === 0) continue;
        if (
          Math.abs(simulation.bunkers.x[cell] - x) <= CONFIG.formation.halfWidth + halfCell
          && Math.abs(simulation.bunkers.y[cell] - y) <= CONFIG.formation.halfHeight + halfCell
        ) {
          simulation.bunkers.destroy(cell);
          removed += 1;
          eventX = simulation.bunkers.x[cell];
          eventY = simulation.bunkers.y[cell];
        }
      }
    }
    if (removed > 0) this._emitBunkerHit(simulation, eventX, eventY, removed, -1);
  }

  interpolate(pool, id, alpha, target) {
    target.x = lerp(pool.previousX[id], pool.x[id], alpha);
    target.y = lerp(pool.previousY[id], pool.y[id], alpha);
    return target;
  }
}

import { EventQueue } from '../../shared/core/EventQueue.js';
import { approach, clamp, mulberry32 } from '../../shared/math/MathUtils.js';
import {
  CONFIG,
  EVENT_TYPES,
  GAME_STATES,
  VFX_PRIORITY,
} from '../config.js';
import {
  BunkerField,
  InvaderField,
  PendingAttackPool,
  ProjectilePool,
  UfoSlot,
} from './EntityPools.js';
import { FormationSystem } from './FormationSystem.js';
import { EnemyFireSystem } from './EnemyFireSystem.js';
import { CombatSystem } from './CombatSystem.js';
import { WaveDirector } from './WaveDirector.js';

const getRandomSeed = () => {
  if (typeof crypto !== 'undefined' && typeof crypto.getRandomValues === 'function') {
    const values = new Uint32Array(1);
    crypto.getRandomValues(values);
    return values[0];
  }
  return (Date.now() ^ 0xa5a5f00d) >>> 0;
};

export class SpaceInvadersSimulation {
  constructor({ seed = getRandomSeed(), highScore = 0 } = {}) {
    this.events = new EventQueue(CONFIG.pools.events);
    this.invaders = new InvaderField();
    this.bunkers = new BunkerField();
    this.playerProjectiles = new ProjectilePool(CONFIG.player.projectilePool);
    this.enemyProjectiles = new ProjectilePool(CONFIG.enemy.projectilePool);
    this.pendingAttacks = new PendingAttackPool();
    this.ufo = new UfoSlot();
    this.formation = new FormationSystem();
    this.enemyFire = new EnemyFireSystem();
    this.combat = new CombatSystem();
    this.waveDirector = new WaveDirector();

    this.seed = seed >>> 0;
    this.random = mulberry32(this.seed);
    this.state = GAME_STATES.TITLE;
    this.previousState = GAME_STATES.TITLE;
    this.wave = 1;
    this.score = 0;
    this.highScore = Math.max(0, Math.floor(highScore));
    this.nextExtraLife = CONFIG.scoring.firstExtraLife;
    this.comboTier = 0;
    this.comboTimer = 0;
    this.shotsFired = 0;
    this.elapsed = 0;
    this.gameOverCause = '';
    this.player = {
      x: 0,
      previousX: 0,
      y: CONFIG.player.y,
      vx: 0,
      active: true,
      lives: CONFIG.player.startLives,
      fireTimer: 0,
      respawnTimer: 0,
      invulnerabilityTimer: 0,
    };
    this.ufo.reset(this.random);
    this.formation.reset(1);
  }

  startCampaign(seed = this.seed) {
    this.seed = seed >>> 0;
    this.random = mulberry32(this.seed);
    this.wave = 1;
    this.score = 0;
    this.nextExtraLife = CONFIG.scoring.firstExtraLife;
    this.comboTier = 0;
    this.comboTimer = 0;
    this.shotsFired = 0;
    this.elapsed = 0;
    this.gameOverCause = '';
    this.player.x = 0;
    this.player.previousX = 0;
    this.player.vx = 0;
    this.player.active = true;
    this.player.lives = CONFIG.player.startLives;
    this.player.fireTimer = 0;
    this.player.respawnTimer = 0;
    this.player.invulnerabilityTimer = 0.9;
    this.invaders.reset();
    this.bunkers.reset();
    this.playerProjectiles.reset();
    this.enemyProjectiles.reset();
    this.pendingAttacks.reset();
    this.ufo.reset(this.random);
    this.formation.reset(1);
    this.enemyFire.reset();
    this.waveDirector.reset();
    this.events.clear();
    this.setState(GAME_STATES.PLAYING);
    const event = this.events.push(EVENT_TYPES.WAVE_STARTED);
    if (event) {
      event.value = 1;
      event.priority = VFX_PRIORITY.HEAVY;
    }
  }

  update(dt, input) {
    if (dt <= 0) return;
    if (this.state === GAME_STATES.WAVE_CLEAR) {
      this.waveDirector.update(dt, this);
      return;
    }
    if (this.state !== GAME_STATES.PLAYING) return;

    this.elapsed += dt;
    this.player.previousX = this.player.x;
    this._updatePlayer(dt, input);
    this.formation.update(dt, this.invaders, this.events);
    this.enemyFire.update(dt, this);
    this.combat.update(dt, this);
    this._updateUfo(dt);
    if (this.comboTimer > 0) {
      this.comboTimer -= dt;
      if (this.comboTimer <= 0) this.comboTier = 0;
    }
    this.waveDirector.update(dt, this);
  }

  _updatePlayer(dt, input) {
    this.player.fireTimer = Math.max(0, this.player.fireTimer - dt);
    this.player.invulnerabilityTimer = Math.max(0, this.player.invulnerabilityTimer - dt);

    if (!this.player.active) {
      this.player.respawnTimer -= dt;
      if (this.player.lives > 0 && this.player.respawnTimer <= 0) {
        this.player.active = true;
        this.player.x = 0;
        this.player.previousX = 0;
        this.player.vx = 0;
        this.player.invulnerabilityTimer = CONFIG.player.invulnerability;
        const event = this.events.push(EVENT_TYPES.PLAYER_RESPAWNED);
        if (event) event.priority = VFX_PRIORITY.MINOR;
      }
      return;
    }

    const axis = clamp(input?.axisX ?? 0, -1, 1);
    const target = axis * CONFIG.player.maxSpeed;
    const rate = axis === 0 ? CONFIG.player.deceleration : CONFIG.player.acceleration;
    this.player.vx = approach(this.player.vx, target, rate * dt);
    this.player.x = clamp(
      this.player.x + this.player.vx * dt,
      CONFIG.world.left + CONFIG.player.halfWidth,
      CONFIG.world.right - CONFIG.player.halfWidth,
    );

    if ((input?.fire ?? false) && this.player.fireTimer <= 0
      && this.playerProjectiles.activeCount < CONFIG.player.activeShotCap) {
      const projectile = this.playerProjectiles.spawn(
        this.player.x,
        this.player.y + 0.65,
        0,
        CONFIG.player.projectileSpeed,
        0,
        0.11,
        0.3,
      );
      if (projectile >= 0) {
        this.player.fireTimer = CONFIG.player.fireCooldown;
        this.shotsFired += 1;
        const event = this.events.push(EVENT_TYPES.PLAYER_SHOT);
        if (event) {
          event.x = this.player.x;
          event.y = this.player.y + 0.65;
          event.speed = CONFIG.player.projectileSpeed;
          event.priority = VFX_PRIORITY.MINOR;
        }
      }
    }
  }

  _updateUfo(dt) {
    if (this.ufo.active) {
      this.ufo.previousX = this.ufo.x;
      this.ufo.x += this.ufo.direction * this.ufo.speed * dt;
      if (this.ufo.x < CONFIG.world.left - 2 || this.ufo.x > CONFIG.world.right + 2) {
        this.ufo.active = false;
        this.ufo.nextSpawn = 14 + this.random() * 12;
        const event = this.events.push(EVENT_TYPES.UFO_EXITED);
        if (event) event.priority = VFX_PRIORITY.AMBIENT;
      }
      return;
    }

    this.ufo.nextSpawn -= dt;
    if (this.ufo.nextSpawn > 0 || this.invaders.aliveCount <= 8) return;
    this.ufo.active = true;
    this.ufo.visitCount += 1;
    this.ufo.direction *= -1;
    this.ufo.x = this.ufo.direction > 0 ? CONFIG.world.left - 1.5 : CONFIG.world.right + 1.5;
    this.ufo.previousX = this.ufo.x;
    this.ufo.speed = 4.1 + 0.12 * this.wave;
    const event = this.events.push(EVENT_TYPES.UFO_SPAWNED);
    if (event) {
      event.x = this.ufo.x;
      event.y = this.ufo.y;
      event.priority = VFX_PRIORITY.MINOR;
    }
  }

  killInvader(id, x, y, speed) {
    if (!this.invaders.kill(id)) return false;
    this.comboTier = this.comboTimer > 0
      ? Math.min(CONFIG.scoring.comboMaxTier, this.comboTier + 1)
      : 0;
    this.comboTimer = CONFIG.scoring.comboWindow;
    const waveMultiplier = 1 + 0.1 * (this.wave - 1);
    const comboMultiplier = 1 + 0.25 * this.comboTier;
    const raw = this.invaders.score[id] * waveMultiplier * comboMultiplier;
    const award = Math.round(raw / 5) * 5;
    this.addScore(award);
    const event = this.events.push(EVENT_TYPES.INVADER_KILLED);
    if (event) {
      event.x = x;
      event.y = y;
      event.value = award;
      event.variant = this.invaders.archetype[id];
      event.source = id;
      event.speed = speed;
      event.priority = this.invaders.aliveCount === 0 ? VFX_PRIORITY.CRITICAL : VFX_PRIORITY.COMBAT;
      event.text = `+${award}`;
    }
    return true;
  }

  killUfo(x, y, speed) {
    if (!this.ufo.active) return false;
    this.ufo.active = false;
    const values = [50, 100, 150, 300];
    const award = values[(this.shotsFired + this.wave + this.ufo.visitCount) % values.length];
    this.addScore(award);
    this.ufo.nextSpawn = 14 + this.random() * 12;
    const event = this.events.push(EVENT_TYPES.UFO_KILLED);
    if (event) {
      event.x = x;
      event.y = y;
      event.value = award;
      event.speed = speed;
      event.priority = VFX_PRIORITY.HEAVY;
      event.text = `MYSTERY +${award}`;
    }
    return true;
  }

  hitPlayer(x, y, speed) {
    if (!this.player.active || this.player.invulnerabilityTimer > 0) return false;
    this.player.active = false;
    this.player.lives -= 1;
    this.player.vx = 0;
    this.player.respawnTimer = CONFIG.player.respawnDelay;
    this.comboTier = 0;
    this.comboTimer = 0;
    for (let id = 0; id < this.enemyProjectiles.capacity; id += 1) {
      if (!this.enemyProjectiles.pool.isActive(id)) continue;
      if (Math.hypot(this.enemyProjectiles.x[id] - x, this.enemyProjectiles.y[id] - y) < 1.6) {
        this.enemyProjectiles.release(id);
      }
    }
    const event = this.events.push(EVENT_TYPES.PLAYER_HIT);
    if (event) {
      event.x = x;
      event.y = y;
      event.speed = speed;
      event.value = this.player.lives;
      event.priority = VFX_PRIORITY.CRITICAL;
    }
    return true;
  }

  addScore(points) {
    this.score += Math.max(0, Math.floor(points));
    this.highScore = Math.max(this.highScore, this.score);
    while (this.score >= this.nextExtraLife && this.player.lives < CONFIG.player.maxLives) {
      this.player.lives += 1;
      this.nextExtraLife += CONFIG.scoring.repeatExtraLife;
      const event = this.events.push(EVENT_TYPES.EXTRA_LIFE);
      if (event) {
        event.value = this.player.lives;
        event.priority = VFX_PRIORITY.HEAVY;
        event.text = 'EXTRA CANNON';
      }
    }
  }

  startNextWave() {
    this.wave += 1;
    this.invaders.reset();
    this.bunkers.repair(0.18, this.random);
    this.playerProjectiles.reset();
    this.enemyProjectiles.reset();
    this.pendingAttacks.reset();
    this.formation.reset(this.wave);
    this.enemyFire.reset();
    this.player.active = true;
    this.player.x = 0;
    this.player.previousX = 0;
    this.player.vx = 0;
    this.player.invulnerabilityTimer = 0.9;
    this.comboTier = 0;
    this.comboTimer = 0;
    this.setState(GAME_STATES.PLAYING);
    const event = this.events.push(EVENT_TYPES.WAVE_STARTED);
    if (event) {
      event.value = this.wave;
      event.priority = VFX_PRIORITY.HEAVY;
    }
  }

  enterVictory() {
    this.setState(GAME_STATES.VICTORY);
    const event = this.events.push(EVENT_TYPES.VICTORY);
    if (event) {
      event.value = this.score;
      event.priority = VFX_PRIORITY.CRITICAL;
    }
  }

  enterGameOver(cause) {
    if (this.state === GAME_STATES.GAME_OVER) return;
    this.gameOverCause = cause;
    this.player.active = false;
    this.setState(GAME_STATES.GAME_OVER);
    const event = this.events.push(EVENT_TYPES.GAME_OVER);
    if (event) {
      event.value = this.score;
      event.cause = cause;
      event.priority = VFX_PRIORITY.CRITICAL;
    }
  }

  setState(nextState) {
    if (nextState === this.state) return;
    this.previousState = this.state;
    this.state = nextState;
    const event = this.events.push(EVENT_TYPES.STATE_CHANGED);
    if (event) {
      event.text = nextState;
      event.cause = this.previousState;
    }
  }

  pause() {
    if (this.state !== GAME_STATES.PLAYING && this.state !== GAME_STATES.WAVE_CLEAR) return false;
    this.previousState = this.state;
    this.state = GAME_STATES.PAUSED;
    const event = this.events.push(EVENT_TYPES.STATE_CHANGED);
    if (event) {
      event.text = GAME_STATES.PAUSED;
      event.cause = this.previousState;
    }
    return true;
  }

  resume() {
    if (this.state !== GAME_STATES.PAUSED) return false;
    const resumeState = this.previousState === GAME_STATES.WAVE_CLEAR
      ? GAME_STATES.WAVE_CLEAR
      : GAME_STATES.PLAYING;
    this.state = resumeState;
    const event = this.events.push(EVENT_TYPES.STATE_CHANGED);
    if (event) {
      event.text = resumeState;
      event.cause = GAME_STATES.PAUSED;
    }
    return true;
  }

  debugKillAllInvaders() {
    this.invaders.alive.fill(0);
    this.invaders.aliveCount = 0;
  }

  debugForceInvasion() {
    this.formation.originY = CONFIG.world.invasionLine - 2;
    this.formation.previousY = this.formation.originY;
  }

  debugSetWave(wave) {
    this.wave = clamp(Math.floor(wave), 1, CONFIG.campaignWaves);
    this.invaders.reset();
    this.formation.reset(this.wave);
  }

  snapshot() {
    return {
      seed: this.seed,
      state: this.state,
      wave: this.wave,
      score: this.score,
      lives: this.player.lives,
      playerX: Number(this.player.x.toFixed(4)),
      invaders: this.invaders.aliveCount,
      bunkerCells: this.bunkers.aliveCount,
      playerShots: this.playerProjectiles.activeCount,
      enemyShots: this.enemyProjectiles.activeCount,
    };
  }

  dispose() {
    this.events.clear();
    this.playerProjectiles.reset();
    this.enemyProjectiles.reset();
    this.pendingAttacks.reset();
  }
}

import { CONFIG, EVENT_TYPES, GAME_STATES, VFX_PRIORITY } from '../config.js';

export class WaveDirector {
  constructor() {
    this.clearTimer = 0;
  }

  reset() {
    this.clearTimer = 0;
  }

  update(dt, simulation) {
    if (simulation.state === GAME_STATES.WAVE_CLEAR) {
      this.clearTimer -= dt;
      if (this.clearTimer > 0) return;
      if (simulation.wave >= CONFIG.campaignWaves) simulation.enterVictory();
      else simulation.startNextWave();
      return;
    }
    if (simulation.state !== GAME_STATES.PLAYING) return;

    if (simulation.player.lives <= 0 && !simulation.player.active) {
      simulation.enterGameOver('cannon destroyed');
      return;
    }

    const extents = simulation.formation.getExtents(simulation.invaders);
    if (extents.minY <= CONFIG.world.invasionLine) {
      simulation.enterGameOver('fleet breach');
      return;
    }

    if (simulation.invaders.aliveCount === 0) {
      if (simulation.player.lives <= 0) {
        simulation.enterGameOver('cannon destroyed');
        return;
      }
      this.clearTimer = 1.6;
      simulation.enemyProjectiles.reset();
      simulation.pendingAttacks.reset();
      simulation.setState(GAME_STATES.WAVE_CLEAR);
      const event = simulation.events.push(EVENT_TYPES.WAVE_CLEAR);
      if (event) {
        event.value = simulation.wave;
        event.priority = simulation.wave >= CONFIG.campaignWaves
          ? VFX_PRIORITY.CRITICAL
          : VFX_PRIORITY.HEAVY;
      }
    }
  }
}

