  const far = setAabb({}, 0, 5, 0.4, 0.4);
  const nearHit = {};
  const farHit = {};
  assert.equal(sweptAabb(0, 0, 0, 8, 0.1, 0.1, near, nearHit), true);
  assert.equal(sweptAabb(0, 0, 0, 8, 0.1, 0.1, far, farHit), true);
  assert.ok(nearHit.time < farHit.time);
});

