import { clamp } from '../math/MathUtils.js';

export class CameraShake {
  constructor(seed = 1) {
    this.trauma = 0;
    this.time = 0;
    this.seed = seed * 0.0137;
    this.reducedMotion = false;
    this.sample = { x: 0, y: 0, z: 0, pitch: 0, yaw: 0, roll: 0 };
  }

  addTrauma(amount) {
    this.trauma = clamp(this.trauma + Math.max(0, amount), 0, 1);
  }

  addImpact(speed, base = 0.06, scale = 0.24) {
    const velocityFactor = clamp((speed - 4) / 18, 0, 1);
    this.addTrauma(base + velocityFactor * scale);
  }

  setReducedMotion(enabled) {
    this.reducedMotion = Boolean(enabled);
  }

  update(dt) {
    this.time += dt;
    this.trauma = Math.max(0, this.trauma - 1.8 * dt);
    const amplitude = this.trauma * this.trauma;
    const translationScale = this.reducedMotion ? 0.25 : 1;
    const rotationScale = this.reducedMotion ? 0 : 1;
    const t = this.time * 31.7 + this.seed;
    const n1 = Math.sin(t * 1.07 + Math.sin(t * 0.37));
    const n2 = Math.sin(t * 1.31 + 2.1 + Math.sin(t * 0.43));
    const n3 = Math.sin(t * 0.89 + 4.7 + Math.sin(t * 0.29));
    this.sample.x = n1 * 0.3 * amplitude * translationScale;
    this.sample.y = n2 * 0.22 * amplitude * translationScale;
    this.sample.z = n3 * 0.08 * amplitude * translationScale;
    this.sample.pitch = n2 * 0.012 * amplitude * rotationScale;
    this.sample.yaw = n1 * 0.008 * amplitude * rotationScale;
    this.sample.roll = n3 * 0.018 * amplitude * rotationScale;
    return this.sample;
  }

  reset() {
    this.trauma = 0;
    this.time = 0;
    Object.keys(this.sample).forEach((key) => { this.sample[key] = 0; });
  }
}

import { clamp, smoothstep } from '../math/MathUtils.js';

export class HitStopController {
  constructor() {
    this.remaining = 0;
    this.duration = 0;
    this.minimumScale = 0;
    this.priority = -1;
    this.admissionCooldown = 0;
    this.enabled = true;
  }

  request(duration, minimumScale = 0, priority = 1) {
    if (!this.enabled || duration <= 0) return false;
    const cappedDuration = Math.min(0.125, duration);
    if (priority <= 2 && this.admissionCooldown > 0) return false;
    if (this.remaining > 0 && priority < this.priority) return false;

    if (priority > this.priority || this.remaining <= 0) {
      this.priority = priority;
      this.minimumScale = clamp(minimumScale, 0, 1);
      this.duration = cappedDuration;
      this.remaining = Math.max(this.remaining, cappedDuration);
    } else {
      this.duration = Math.max(this.duration, cappedDuration);
      this.remaining = Math.max(this.remaining, cappedDuration);
      this.minimumScale = Math.min(this.minimumScale, clamp(minimumScale, 0, 1));
    }
    if (priority <= 2) this.admissionCooldown = 0.045;
    return true;
  }

  consume(realDt) {
    this.admissionCooldown = Math.max(0, this.admissionCooldown - realDt);
    if (!this.enabled || this.remaining <= 0) return realDt;
    this.remaining = Math.max(0, this.remaining - realDt);
    const progress = this.duration <= 0 ? 1 : 1 - this.remaining / this.duration;
    const scale = progress < 0.6
      ? this.minimumScale
      : this.minimumScale + (1 - this.minimumScale) * smoothstep(0.6, 1, progress);
    if (this.remaining === 0) {
      this.priority = -1;
      this.duration = 0;
      this.minimumScale = 0;
    }
    return realDt * scale;
  }

  setEnabled(enabled) {
    this.enabled = Boolean(enabled);
    if (!this.enabled) this.reset();
  }

  reset() {
    this.remaining = 0;
    this.duration = 0;
    this.minimumScale = 0;
    this.priority = -1;
    this.admissionCooldown = 0;
  }
}

import { clamp } from '../math/MathUtils.js';

export class PerformanceMonitor {
  constructor() {
    this.samples = new Float32Array(180);
    this.cursor = 0;
    this.count = 0;
    this.sum = 0;
    this.slowSeconds = 0;
    this.fastSeconds = 0;
    this.droppedSimulationTime = 0;
    this.spawnFailures = 0;
  }

  update(frameDt) {
    const ms = clamp(frameDt * 1000, 0, 250);
    if (this.count < this.samples.length) this.count += 1;
    else this.sum -= this.samples[this.cursor];
    this.samples[this.cursor] = ms;
    this.sum += ms;
    this.cursor = (this.cursor + 1) % this.samples.length;
    const average = this.averageMs;
    this.slowSeconds = average > 23 ? this.slowSeconds + frameDt : 0;
    this.fastSeconds = average < 17.5 ? this.fastSeconds + frameDt : 0;
  }

  addDroppedTime(seconds) {
    this.droppedSimulationTime += seconds;
  }

  get averageMs() {
    return this.count === 0 ? 0 : this.sum / this.count;
  }

  qualityRecommendation(currentCap) {
    if (this.slowSeconds > 3 && currentCap > 1.25) {
      this.slowSeconds = 0;
      return 1.25;
    }
    if (this.fastSeconds > 12 && currentCap < 1.75) {
      this.fastSeconds = 0;
      return 1.75;
    }
    return currentCap;
  }

  snapshot() {
    return {
      averageMs: Number(this.averageMs.toFixed(2)),
      droppedSimulationTime: Number(this.droppedSimulationTime.toFixed(3)),
      spawnFailures: this.spawnFailures,
    };
  }
}

import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';

export class RenderPipeline {
  constructor({
    canvas,
    scene,
    camera,
    onResize = () => {},
    onContextLost = () => {},
    onContextRestored = () => {},
    bloom = {},
  }) {
    this.canvas = canvas;
    this.scene = scene;
    this.camera = camera;
    this.onResize = onResize;
    this.onContextLost = onContextLost;
    this.onContextRestored = onContextRestored;
    this.abortController = new AbortController();
    this.pixelRatioCap = 1.75;
    this.width = 1;
    this.height = 1;
    this.suspended = false;
    this.contextLost = false;
    this.baseBloomStrength = bloom.strength ?? 0.9;
    this.bloomPulse = 0;

    this.renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: true,
      alpha: false,
      powerPreference: 'high-performance',
    });
    this.renderer.setClearColor(0x02040b, 1);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = bloom.exposure ?? 1.05;
    this.renderer.shadowMap.enabled = false;

    this.renderPass = new RenderPass(scene, camera);
    this.bloomPass = new UnrealBloomPass(
      new THREE.Vector2(1, 1),
      this.baseBloomStrength,
      bloom.radius ?? 0.28,
      bloom.threshold ?? 0.86,
    );
    this.outputPass = new OutputPass();
    this.composer = new EffectComposer(this.renderer);
    this.composer.addPass(this.renderPass);
    this.composer.addPass(this.bloomPass);
    this.composer.addPass(this.outputPass);

    this._installLifecycle();
    this.resize();
  }

  _installLifecycle() {
    const options = { signal: this.abortController.signal };
    this.canvas.addEventListener('webglcontextlost', (event) => {
      event.preventDefault();
      this.contextLost = true;
      this.onContextLost();
    }, options);
    this.canvas.addEventListener('webglcontextrestored', () => {
      this.contextLost = false;
      this.resize();
      this.onContextRestored();
    }, options);

    if (typeof ResizeObserver === 'function') {
      this.resizeObserver = new ResizeObserver(() => this.resize());
      this.resizeObserver.observe(this.canvas.parentElement ?? this.canvas);
    } else {
      window.addEventListener('resize', () => this.resize(), options);
    }
  }

  resize() {
    const rect = this.canvas.getBoundingClientRect();
    const width = Math.floor(rect.width || window.innerWidth || 0);
    const height = Math.floor(rect.height || window.innerHeight || 0);
    if (width <= 0 || height <= 0) {
      this.suspended = true;
      return;
    }
    this.suspended = false;
    this.width = width;
    this.height = height;
    const pixelRatio = Math.min(window.devicePixelRatio || 1, this.pixelRatioCap);
    this.renderer.setPixelRatio(pixelRatio);
    this.renderer.setSize(width, height, false);
    if (typeof this.composer.setPixelRatio === 'function') this.composer.setPixelRatio(pixelRatio);
    this.composer.setSize(width, height);
    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();
    this.onResize(width, height);
  }

  setPixelRatioCap(cap) {
    const next = Math.max(1, Math.min(1.75, cap));
    if (next === this.pixelRatioCap) return;
    this.pixelRatioCap = next;
    this.resize();
  }

  pulseBloom(amount = 0.18) {
    this.bloomPulse = Math.max(this.bloomPulse, Math.min(0.18, amount));
  }

  update(realDt, reducedFlashes = false) {
    this.bloomPulse *= Math.exp(-6.5 * realDt);
    this.bloomPass.strength = this.baseBloomStrength + (reducedFlashes ? 0 : this.bloomPulse);
  }

  render(realDt) {
    if (this.suspended || this.contextLost) return;
    this.composer.render(realDt);
  }

  memorySnapshot() {
    return {
      geometries: this.renderer.info.memory.geometries,
      textures: this.renderer.info.memory.textures,
      calls: this.renderer.info.render.calls,
      triangles: this.renderer.info.render.triangles,
    };
  }

  dispose() {
    this.abortController.abort();
    this.resizeObserver?.disconnect();
    if (typeof this.renderPass.dispose === 'function') this.renderPass.dispose();
    if (typeof this.bloomPass.dispose === 'function') this.bloomPass.dispose();
    if (typeof this.outputPass.dispose === 'function') this.outputPass.dispose();
    if (typeof this.composer.dispose === 'function') this.composer.dispose();
    this.renderer.dispose();
  }
}

import * as THREE from 'three';

const isTexture = (value) => value instanceof THREE.Texture;

export class ResourceTracker {
  constructor() {
    this.resources = new Set();
    this.disposed = false;
  }

  track(resource) {
    if (!resource || this.disposed) return resource;
    this.resources.add(resource);

    if (resource instanceof THREE.Object3D) {
      resource.traverse((object) => {
        this.resources.add(object);
        if (object.geometry) this.resources.add(object.geometry);
        if (Array.isArray(object.material)) object.material.forEach((material) => this._trackMaterial(material));
        else if (object.material) this._trackMaterial(object.material);
      });
    } else if (resource instanceof THREE.Material) {
      this._trackMaterial(resource);
    }
    return resource;
  }

  _trackMaterial(material) {
    this.resources.add(material);
    for (const value of Object.values(material)) {
      if (isTexture(value)) this.resources.add(value);
    }
  }

  untrack(resource) {
    this.resources.delete(resource);
    return resource;
  }

  dispose() {
    if (this.disposed) return;
    this.disposed = true;
    for (const resource of this.resources) {
      if (resource instanceof THREE.Object3D && resource.parent) resource.parent.remove(resource);
    }
    for (const resource of this.resources) {
      if (typeof resource.dispose === 'function') resource.dispose();
    }
    this.resources.clear();
  }
}

