import * as THREE from 'three';
import { lerp } from '../../shared/math/MathUtils.js';
import { CONFIG, PALETTE } from '../config.js';
import { createProjectileGeometries } from './GeometryFactory.js';

export class ProjectileRenderer {
  constructor(scene, tracker, materials) {
    this.scene = scene;
    this.dummy = new THREE.Object3D();
    this.color = new THREE.Color();
    const geometries = createProjectileGeometries();
    this.playerMesh = this._createMesh(geometries[0], materials.playerProjectile, CONFIG.player.projectilePool, 'player-projectiles');
    this.enemyMeshes = [0, 1, 2].map((type) => this._createMesh(
      geometries[type + 1],
      materials.enemyProjectiles[type],
      CONFIG.enemy.projectilePool,
      `enemy-projectiles-${type}`,
    ));
    this.telegraphGeometry = new THREE.TorusGeometry(0.23, 0.042, 5, 16);
    this.telegraphMesh = this._createMesh(
      this.telegraphGeometry,
      materials.enemyProjectiles[1],
      CONFIG.enemy.pendingPool,
      'enemy-telegraphs',
    );
    for (const mesh of [this.playerMesh, ...this.enemyMeshes, this.telegraphMesh]) tracker.track(mesh);
  }

  _createMesh(geometry, material, capacity, name) {
    const mesh = new THREE.InstancedMesh(geometry, material, capacity);
    mesh.name = name;
    mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    mesh.frustumCulled = false;
    mesh.count = 0;
    this.scene.add(mesh);
    return mesh;
  }

  update(simulation, alpha, elapsed) {
    let packed = 0;
    const player = simulation.playerProjectiles;
    for (let id = 0; id < player.capacity; id += 1) {
      if (!player.pool.isActive(id)) continue;
      this.dummy.position.set(
        lerp(player.previousX[id], player.x[id], alpha),
        lerp(player.previousY[id], player.y[id], alpha),
        0.12,
      );
      this.dummy.rotation.set(0, 0, 0);
      this.dummy.scale.setScalar(1);
      this.dummy.updateMatrix();
      this.playerMesh.setMatrixAt(packed, this.dummy.matrix);
      this.color.setHex(PALETTE.cyan).multiplyScalar(2.2);
      this.playerMesh.setColorAt(packed, this.color);
      packed += 1;
    }
    this.playerMesh.count = packed;
    this.playerMesh.instanceMatrix.needsUpdate = true;
    this.playerMesh.instanceColor.needsUpdate = true;

    const counts = new Uint16Array(3);
    const enemy = simulation.enemyProjectiles;
    for (let id = 0; id < enemy.capacity; id += 1) {
      if (!enemy.pool.isActive(id)) continue;
      const type = enemy.kind[id];
      const mesh = this.enemyMeshes[type];
      const index = counts[type]++;
      this.dummy.position.set(
        lerp(enemy.previousX[id], enemy.x[id], alpha),
        lerp(enemy.previousY[id], enemy.y[id], alpha),
        0.1,
      );
      this.dummy.rotation.set(0, 0, type === 2 ? Math.atan2(enemy.vy[id], enemy.vx[id]) + Math.PI * 0.5 : elapsed * (type === 1 ? 7 : 0));
      this.dummy.scale.setScalar(1);
      this.dummy.updateMatrix();
      mesh.setMatrixAt(index, this.dummy.matrix);
      this.color.setHex(type === 0 ? PALETTE.red : type === 1 ? PALETTE.amber : PALETTE.magenta).multiplyScalar(2);
      mesh.setColorAt(index, this.color);
    }
    for (let type = 0; type < 3; type += 1) {
      const mesh = this.enemyMeshes[type];
      mesh.count = counts[type];
      mesh.instanceMatrix.needsUpdate = true;
      if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    }

    packed = 0;
    const pending = simulation.pendingAttacks;
    for (let id = 0; id < pending.capacity; id += 1) {
      if (!pending.pool.isActive(id)) continue;
      const shooter = pending.shooter[id];
      if (simulation.invaders.alive[shooter] === 0) continue;
      const pulse = 0.78 + 0.3 * Math.sin(elapsed * 28 + id);
      this.dummy.position.set(
        simulation.formation.originX + simulation.invaders.localX[shooter],
        simulation.formation.originY + simulation.invaders.localY[shooter] - 0.48,
        0.04,
      );
      this.dummy.rotation.set(0, 0, 0);
      this.dummy.scale.setScalar(pulse);
      this.dummy.updateMatrix();
      this.telegraphMesh.setMatrixAt(packed++, this.dummy.matrix);
    }
    this.telegraphMesh.count = packed;
    this.telegraphMesh.instanceMatrix.needsUpdate = true;
  }

  dispose() {
    this.scene.remove(this.playerMesh, ...this.enemyMeshes, this.telegraphMesh);
  }
}

import * as THREE from 'three';
import { mulberry32 } from '../../shared/math/MathUtils.js';
import { PALETTE } from '../config.js';
import { createDeckGridTexture, createMetalTexture } from './ProceduralTextures.js';

export class EnvironmentRenderer {
  constructor(scene, tracker, materials, renderer) {
    this.scene = scene;
    this.materials = materials;
    this.dummy = new THREE.Object3D();
    this.color = new THREE.Color();
    this.pulse = 0;
    this.group = new THREE.Group();
    this.group.name = 'procedural-environment';

    const deckTexture = tracker.track(createDeckGridTexture(renderer));
    materials.deck.map = deckTexture;
    materials.deck.needsUpdate = true;
    const deckGeometry = new THREE.PlaneGeometry(32, 20, 1, 1);
    this.deck = new THREE.Mesh(deckGeometry, materials.deck);
    this.deck.rotation.x = -Math.PI * 0.5;
    this.deck.position.set(0, -9.55, -1.4);
    this.group.add(this.deck);

    const metalTexture = tracker.track(createMetalTexture(renderer));
    materials.backdrop.map = metalTexture;
    materials.backdrop.needsUpdate = true;
    this.backdrop = new THREE.Mesh(new THREE.PlaneGeometry(31, 22), materials.backdrop);
    this.backdrop.position.set(0, 0.2, -5.2);
    this.group.add(this.backdrop);

    this.starCount = 192;
    this.starX = new Float32Array(this.starCount);
    this.starY = new Float32Array(this.starCount);
    this.starZ = new Float32Array(this.starCount);
    this.starPhase = new Float32Array(this.starCount);
    this.stars = new THREE.InstancedMesh(
      new THREE.IcosahedronGeometry(0.055, 0),
      materials.star,
      this.starCount,
    );
    this.stars.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.stars.frustumCulled = false;
    const random = mulberry32(0x5a771e);
    for (let i = 0; i < this.starCount; i += 1) {
      this.starX[i] = (random() - 0.5) * 30;
      this.starY[i] = (random() - 0.42) * 23;
      this.starZ[i] = -1.2 - random() * 3.4;
      this.starPhase[i] = random() * Math.PI * 2;
    }
    this.group.add(this.stars);

    this.railCount = 36;
    this.rails = new THREE.InstancedMesh(
      new THREE.BoxGeometry(1, 1, 1),
      materials.rail,
      this.railCount,
    );
    this.rails.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.rails.frustumCulled = false;
    this._layoutRails();
    this.group.add(this.rails);

    scene.add(this.group);
    tracker.track(this.group);
  }

  _layoutRails() {
    let index = 0;
    for (const side of [-1, 1]) {
      for (let segment = 0; segment < 12; segment += 1) {
        this.dummy.position.set(side * 12.25, -8.8 + segment * 1.6, -0.65);
        this.dummy.scale.set(0.06, 0.62, 0.1);
        this.dummy.rotation.set(0, 0, 0);
        this.dummy.updateMatrix();
        this.rails.setMatrixAt(index, this.dummy.matrix);
        this.color.setHex(side < 0 ? PALETTE.cyan : PALETTE.magenta).multiplyScalar(1.5);
        this.rails.setColorAt(index, this.color);
        index += 1;
      }
    }
    for (let segment = 0; segment < 12; segment += 1) {
      this.dummy.position.set(-11 + segment * 2, -9.25, -0.3);
      this.dummy.scale.set(0.78, 0.045, 0.1);
      this.dummy.updateMatrix();
      this.rails.setMatrixAt(index, this.dummy.matrix);
      this.color.setHex(PALETTE.cyan).multiplyScalar(1.2);
      this.rails.setColorAt(index, this.color);
      index += 1;
    }
    this.rails.count = index;
    this.rails.instanceMatrix.needsUpdate = true;
    this.rails.instanceColor.needsUpdate = true;
  }

  triggerPulse(amount = 1) {
    this.pulse = Math.max(this.pulse, amount);
  }

  update(dt, elapsed) {
    this.pulse *= Math.exp(-3.5 * dt);
    this.materials.deck.emissiveIntensity = 0.72 + this.pulse * 0.5;
    for (let i = 0; i < this.starCount; i += 1) {
      const scale = 0.52 + 0.48 * (0.5 + 0.5 * Math.sin(elapsed * 1.4 + this.starPhase[i]));
      this.dummy.position.set(this.starX[i], this.starY[i], this.starZ[i]);
      this.dummy.rotation.set(0, 0, 0);
      this.dummy.scale.setScalar(scale);
      this.dummy.updateMatrix();
      this.stars.setMatrixAt(i, this.dummy.matrix);
      this.color.setHex(PALETTE.white).multiplyScalar(0.7 + scale * 0.85);
      this.stars.setColorAt(i, this.color);
    }
    this.stars.instanceMatrix.needsUpdate = true;
    this.stars.instanceColor.needsUpdate = true;
  }

  dispose() {
    this.scene.remove(this.group);
  }
}

import * as THREE from 'three';
import { CONFIG } from '../config.js';
import { createBunkerGeometry } from './GeometryFactory.js';

export class DefenseRenderer {
  constructor(scene, tracker, material) {
    this.scene = scene;
    this.dummy = new THREE.Object3D();
    this.color = new THREE.Color();
    this.mesh = new THREE.InstancedMesh(createBunkerGeometry(), material, CONFIG.bunker.capacity);
    this.mesh.name = 'bunker-voxels';
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.mesh.frustumCulled = false;
    this.mesh.count = 0;
    scene.add(this.mesh);
    tracker.track(this.mesh);
  }

  update(simulation, elapsed) {
    let packed = 0;
    for (let id = 0; id < simulation.bunkers.capacity; id += 1) {
      if (simulation.bunkers.alive[id] === 0) continue;
      this.dummy.position.set(simulation.bunkers.x[id], simulation.bunkers.y[id], -0.02);
      this.dummy.rotation.set(0, 0, 0);
      this.dummy.scale.setScalar(1);
      this.dummy.updateMatrix();
      this.mesh.setMatrixAt(packed, this.dummy.matrix);
