        break;
      case EVENT_TYPES.GAME_OVER:
        this.ui.announce(`Game over. ${event.cause}.`);
        this._persistProgress();
        break;
      default:
        break;
    }
    if (this.simulation.highScore > this.profile.highScore) this.profile.highScore = this.simulation.highScore;
  }

